// Recuperamos las facturas vencidas desde SQL
// (ignoramos el item vacío que genera alwaysOutputData si SQL no devuelve filas)
const facturas = $('Microsoft SQL').all()
  .map(item => item.json)
  .filter(f => f.ClaveCartera);

// Recuperamos el historial de Google Sheets
const historial = $input.all()
  .map(item => item.json)
  .filter(row => row.ID_Cartera);

// Identificamos las facturas que YA tienen
// un aviso de vencimiento enviado.
const avisosEnviados = new Set(
  historial
    .filter(row =>
      String(row.Tipo_Aviso ?? '').trim().toLowerCase() === 'vencido' &&
      String(row.Estado ?? '').trim().toLowerCase() === 'enviado'
    )
    .map(row => String(row.ID_Cartera).trim())
);

// Descartamos las facturas que ya recibieron
// su aviso de vencimiento.
const pendientes = facturas.filter(factura =>
  !avisosEnviados.has(String(factura.ClaveCartera).trim())
);

// Si no queda nada por notificar devolvemos un marcador
// que el IF siguiente deriva al correo de "sin pendientes".
if (pendientes.length === 0) {
  return [{
    json: {
      sinPendientes: true,
      facturasVencidasEnCartera: facturas.length,
      fecha: new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' })
    }
  }];
}

// Devolvemos únicamente las pendientes
return pendientes.map(factura => ({
  json: factura
}));

const facturas = $input.all().map(item => item.json);

const grupos = {};

for (const f of facturas) {

  // Agrupamos por empresa y cliente
  const clave = `${f.Empresa}-${f.Cliente}`;

  if (!grupos[clave]) {
    grupos[clave] = {
      Empresa: f.Empresa,
      Cliente: f.Cliente,
      Emails: new Set(),
      Facturas: [],
      Total: 0
    };
  }

  // Separamos los correos por ; o ,
  const emails = String(f.EmailDestino || '')
    .split(/[;,]/)
    .map(email => email.trim())
    .filter(email => email.length > 0);

  emails.forEach(email => grupos[clave].Emails.add(email));

  // Conservamos todos los datos de la factura
  grupos[clave].Facturas.push(f);

  grupos[clave].Total += Number(f.Importe) || 0;
}

// Generamos una salida por cliente
return Object.values(grupos).map(g => ({
  json: {
    Empresa: g.Empresa,
    Cliente: g.Cliente,
    EmailDestino: [...g.Emails].join(','),
    NumeroFacturas: g.Facturas.length,
    Facturas: g.Facturas,
    Total: Math.round(g.Total * 100) / 100
  }
}));

//
// LOG DE ENVÍOS - AVISOS VENCIDOS
// Genera una fila por factura de cada correo enviado correctamente.
//

// Envíos correctos devueltos por Outlook
const resultados = $input.all();

// Grupos originales preparados para el envío
const grupos = $('Preparar correo vencido').all();

const registros = [];
const fechaEnvio = new Date().toISOString();

for (const r of resultados) {

  // Emparejamos por pairedItem (no por posición): si algún envío
  // falla, los índices de la salida correcta ya no coinciden.
  const p = Array.isArray(r.pairedItem) ? r.pairedItem[0] : r.pairedItem;
  const idx = (p && typeof p === 'object') ? p.item : p;

  const grupo = grupos[idx]?.json;

  if (!grupo) {
    throw new Error(
      `No se encuentra el grupo correspondiente al envío (pairedItem ${idx})`
    );
  }

  // Una fila por factura del cliente
  for (const f of grupo.Facturas) {

    registros.push({
      json: {
        ID_Cartera: f.ClaveCartera,

        // Identificador por factura y tipo de aviso
        ClaveEnvio: `${f.ClaveCartera}-Vencido`,

        Empresa: f.Empresa,
        Cliente: f.Cliente,
        NombreCliente: f.NombreCliente,
        Factura: f.Factura,

        Tipo_Aviso: 'Vencido',

        Fecha_Vencimiento: f.FechaVencimiento,
        Importe: f.Importe,
        Fecha_Envio: fechaEnvio,

        // Destinatarios reales del correo (cliente)
        EmailDestino: grupo.EmailDestino,

        Estado: 'Enviado',
        Error: ''
      }
    });

  }
}

return registros;

//
// PREPARAR CORREO DE RECLAMACIÓN
// Facturas vencidas hace 7 días o más
//

const grupos = $input.all();

return grupos.map(item => {

  const g = item.json;

  // Formato de importes en euros
  const euros = valor =>
    Number(valor).toLocaleString('es-ES', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }) + ' €';

  // Formato de fecha español
  const fecha = valor => {
    if (!valor) return '';
    const s = String(valor).substring(0, 10);
    const [a, m, d] = s.split('-');
    return `${d}/${m}/${a}`;
  };

  // Generamos las filas de las facturas
  const filas = g.Facturas.map(f => `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;">
        ${f.Factura}
      </td>
      <td style="padding:8px;border:1px solid #ddd;">
        ${fecha(f.FechaVencimiento)}
      </td>
      <td style="padding:8px;border:1px solid #ddd;text-align:right;">
        ${euros(f.Importe)}
      </td>
    </tr>
  `).join('');

  const html = `
    <p>Estimado/a cliente:</p>

    <p>
      Según nuestros registros, a fecha de hoy constan
      pendientes de pago las siguientes facturas,
      cuyos vencimientos ya han sido superados:
    </p>

    <table style="border-collapse:collapse;width:100%;">
      <thead>
        <tr style="background-color:#eeeeee;">
          <th style="padding:8px;border:1px solid #ddd;">Factura</th>
          <th style="padding:8px;border:1px solid #ddd;">Vencimiento</th>
          <th style="padding:8px;border:1px solid #ddd;">Importe</th>
        </tr>
      </thead>
      <tbody>
        ${filas}
        <tr>
          <td colspan="2" style="padding:8px;text-align:right;border:1px solid #ddd;">
            <strong>Total pendiente:</strong>
          </td>
          <td style="padding:8px;text-align:right;border:1px solid #ddd;">
            <strong>${euros(g.Total)}</strong>
          </td>
        </tr>
      </tbody>
    </table>

    <p>
      Le agradeceríamos que revisara esta situación y,
      en caso de no haber realizado todavía el pago,
      procediera a su regularización a la mayor brevedad posible.
    </p>

    <p>
      Si el pago ya se ha efectuado, le rogamos que nos lo
      comunique para poder actualizar nuestros registros.
    </p>

    <p>
      Quedamos a su disposición para cualquier aclaración.
    </p>

    <p>
  Un cordial saludo,<br><br>

  <strong>Departamento de Administración y Cobros</strong><br>
  <strong>DIANIA LOGISTICS, S.L.</strong><br>
  <a href="mailto:cobros@diania.es"
     style="color:#24804b;text-decoration:none;">
    cobros@diania.es
  </a>
</p>
  `;

  return {
    json: {
      ...g,
      Asunto: `Aviso de facturas pendientes de pago - ${g.Facturas[0].NombreCliente} - Diania`,
      CuerpoHTML: html
    }
  };

});

//
// LOG DE ERRORES - AVISOS VENCIDOS
// Salida de error de 'Send a message': registra las facturas
// cuyo correo NO se ha podido enviar. Estado = 'Error', por lo que
// el filtro de pendientes las volverá a intentar en la siguiente
// ejecución (solo descarta las que están en 'Enviado').
//

const fallos = $input.all();
const grupos = $('Preparar correo vencido').all();

const registros = [];
const fechaEnvio = new Date().toISOString();

for (const r of fallos) {

  const p = Array.isArray(r.pairedItem) ? r.pairedItem[0] : r.pairedItem;
  const idx = (p && typeof p === 'object') ? p.item : p;

  const grupo = grupos[idx]?.json;
  if (!grupo) continue;

  const err = r.json?.error;
  const mensaje = typeof err === 'string'
    ? err
    : (err?.message ?? JSON.stringify(err ?? r.json));

  for (const f of grupo.Facturas) {

    registros.push({
      json: {
        ID_Cartera: f.ClaveCartera,
        ClaveEnvio: `${f.ClaveCartera}-Vencido`,
        Empresa: f.Empresa,
        Cliente: f.Cliente,
        NombreCliente: f.NombreCliente,
        Factura: f.Factura,
        Tipo_Aviso: 'Vencido',
        Fecha_Vencimiento: f.FechaVencimiento,
        Importe: f.Importe,
        Fecha_Envio: fechaEnvio,
        EmailDestino: grupo.EmailDestino,
        Estado: 'Error',
        Error: String(mensaje).substring(0, 500)
      }
    });

  }
}

return registros;

